{"cards": [{"node_code": "N_99b7c6f28d7c3a3f", "definition": "研究由六个旋转关节依次连接构成的通用机械臂本体结构，涵盖关节布局、连杆几何、负载能力分析及典型工业应用场景。", "boundary": "聚焦于六自由度串联开链结构的物理本体设计与构型特性。边界在于强调“六轴”与“全旋转关节”特征，不涉及SCARA等混合关节构型（归入兄弟节点），也不涉及具体的运动学解算算法或控制策略。纯关节电机或传动元件设计归入“机器人关节、连杆与臂部结构”。", "includes": ["六轴关节型机械臂的连杆尺寸、关节角度范围及结构强度设计", "通用工业机器人本体的构型优化与负载-刚度特性分析", "六轴机械臂在焊接、搬运、装配等场景的本体适配性设计"], "excludes": ["SCARA、直角坐标或圆柱坐标等非全旋转关节构型", "基于六轴结构的正逆运动学解算、轨迹规划或力控算法"], "sibling_distinctions": [{"other_code": "N_8c0b20c7b1a045e6", "rule": "本节点关注全旋转关节的六轴构型，兄弟节点关注包含平移关节或特定混合关节的SCARA、直角坐标及圆柱坐标构型。"}, {"other_code": "N_6e84540e33a8cafb", "rule": "本节点关注通用工业六轴机械臂的标准本体设计，兄弟节点关注具备力矩传感、轻量化或双臂协同等特殊功能的协作及轻量级机械臂。"}], "cross_boundary_rule": "若研究内容涉及六轴机械臂的具体关节内部结构，关节本体主挂载“机器人关节、连杆与臂部结构”，整体六轴臂部构型主挂载本节点。"}, {"node_code": "N_8c0b20c7b1a045e6", "definition": "研究SCARA、直角坐标及圆柱坐标等特定串联构型机器人的本体结构，涵盖混合关节布局、导轨设计及高刚性平面运动特性。", "boundary": "聚焦于非全旋转关节或具有特定几何约束的串联机械臂本体。边界在于强调“混合关节”或“特定坐标系”结构特征，不涉及全旋转六轴构型（归入“关节型六轴机械臂”），也不涉及具体的运动学解算或控制算法。纯导轨或直线驱动元件设计归入“机器人关节、连杆与臂部结构”。", "includes": ["SCARA机器人的平面高刚性结构设计与垂直轴布局", "直角坐标（笛卡尔）机器人的三轴导轨及框架结构设计", "圆柱坐标机器人的旋转-平移混合关节本体构型"], "excludes": ["全旋转关节的六轴通用机械臂本体设计", "基于上述构型的运动学解算、轨迹规划或伺服控制策略"], "sibling_distinctions": [{"other_code": "N_99b7c6f28d7c3a3f", "rule": "本节点关注包含平移关节或特定混合关节的SCARA、直角坐标及圆柱坐标构型，兄弟节点关注全旋转关节的六轴通用构型。"}, {"other_code": "N_6e84540e33a8cafb", "rule": "本节点关注特定坐标系的工业机械臂本体，兄弟节点关注具备人机协作、轻量化或双臂协同功能的机械臂本体。"}], "cross_boundary_rule": "若研究内容涉及SCARA或直角坐标机器人的具体直线驱动或旋转关节设计，关节本体主挂载“机器人关节、连杆与臂部结构”，整体特定坐标构型主挂载本节点。"}, {"node_code": "N_6e84540e33a8cafb", "definition": "研究协作机器人、双臂系统及轻量级机械臂的本体结构，涵盖力矩传感集成、轻量化材料应用、安全碰撞检测及双臂协同构型。", "boundary": "聚焦于具备特殊功能（如协作、轻量、双臂）的串联机械臂本体设计。边界在于强调“人机协作”、“轻量化”或“多臂协同”的结构特征，不涉及通用工业六轴机械臂的标准本体（归入“关节型六轴机械臂”），也不涉及具体的协作控制算法或安全逻辑。纯传感器硬件设计归入“测量与仪器仪表”。", "includes": ["协作机器人（Cobot）的力矩传感集成、柔性关节及轻量化结构设计", "双臂机械臂的基座布局、工作空间重叠分析及协同构型设计", "轻量级机械臂的复合材料应用、减重优化及安全碰撞结构"], "excludes": ["通用工业六轴机械臂的标准本体设计与构型分析", "基于协作或双臂结构的运动学解算、轨迹规划或力控算法"], "sibling_distinctions": [{"other_code": "N_99b7c6f28d7c3a3f", "rule": "本节点关注具备协作、轻量化或双臂协同等特殊功能的机械臂本体，兄弟节点关注通用工业六轴机械臂的标准本体设计。"}, {"other_code": "N_8c0b20c7b1a045e6", "rule": "本节点关注协作、轻量或双臂功能的机械臂本体，兄弟节点关注SCARA、直角坐标及圆柱坐标等特定坐标系的机械臂本体。"}], "cross_boundary_rule": "若研究内容涉及协作机器人的具体力矩传感器或轻量化关节设计，传感器或关节本体主挂载“机器人关节、连杆与臂部结构”或“测量与仪器仪表”，整体协作/轻量/双臂构型主挂载本节点。"}]}
